// slang-emit-metal-prelude.cpp
#include "slang-emit-metal.h"

namespace Slang
{

// State is the struct generated by createCandidateStateLayout. That function preserves these
// field names so the prelude can use the generated layout without defining a second copy of it.
const char* MetalSourceEmitter::kMetalBuiltinPreludeReportHit = R"(
template<typename Attributes>
inline void _slang_storeHitAttributes(
    thread void* destination,
    const thread Attributes* attributes)
{
    *static_cast<thread Attributes*>(destination) = *attributes;
}

// Empty source attributes have no storage. Their address is a null void pointer.
inline void _slang_storeHitAttributes(thread void*, const thread void*)
{
}

template<typename Attributes, typename State>
inline uint _slang_metalReportHit(
    thread State* state,
    thread uchar* globals,
    metal::visible_function_table<uint(thread void*, thread uchar*)> anyHitFunctions,
    uint anyHitIndex,
    float distance,
    uint hitKind,
    const thread Attributes* attributes)
{
    // These values are the fixed AnyHit return contract (CandidateExit in candidate lowering).
    constexpr uint accept = 0;
    constexpr uint ignore = 1;
    constexpr uint endSearch = 2;

    // Reject before changing any state. This comparison also rejects a NaN distance or limit.
    if (!(distance >= state->minDistance && distance <= state->currentMax))
        return ignore;

    // AnyHit reads the proposed hit through the same state pointer as Intersection.
    state->candidateDistance = distance;
    state->candidateHitKind = hitKind;
    _slang_storeHitAttributes(state->candidateAttributes, attributes);

    uint decision = accept;
    if (anyHitIndex != 0xffffffffu && !state->opaque)
        decision = anyHitFunctions[anyHitIndex](static_cast<thread void*>(state), globals);

    // Keep AnyHit's payload writes, but leave the previously accepted hit unchanged.
    if (decision == ignore)
        return ignore;

    // Commit before returning EndSearch so the native callback returns this accepted hit.
    state->accepted = true;
    state->currentMax = distance;
    _slang_storeHitAttributes(state->committedAttributes, attributes);
    *state->committedHitKind = hitKind;

    constexpr uint acceptFirstHitFlag = 0x4u;
    if (decision == endSearch || (state->rayFlags & acceptFirstHitFlag) != 0)
        return endSearch;
    return accept;
}
)";

const char* MetalSourceEmitter::kMetalBuiltinPreludeMatrixCompMult = R"(
template<typename T, int A, int B>
matrix<T,A,B> _slang_matrixCompMult(matrix<T,A,B> m1, matrix<T,A,B> m2)
{
    matrix<T,A,B> result;
    for (int i = 0; i < A; i++)
        result[i] = m1[i] * m2[i];
    return result;
}
)";

const char* MetalSourceEmitter::kMetalBuiltinPreludeMatrixReshape = R"(
template<int A, int B, typename T, int N, int M>
matrix<T,A,B> _slang_matrixReshape(matrix<T,N,M> m)
{
    matrix<T,A,B> result = T(0);
    for (int i = 0; i < min(A,N); i++)
        for (int j = 0; j < min(B,M); j++)
            result[i] = m[i][j];
    return result;
}
)";

const char* MetalSourceEmitter::kMetalBuiltinPreludeVectorReshape = R"(
template<int A, typename T, int N>
vec<T,A> _slang_vectorReshape(vec<T,N> v)
{
    vec<T,A> result = T(0);
    for (int i = 0; i < min(A,N); i++)
        result[i] = v[i];
    return result;
}
)";

const char* MetalSourceEmitter::kMetalBuiltinPreludeMatrixFmod = R"(
template<typename T, int A, int B>
matrix<T,A,B> _slang_matrixFmod(matrix<T,A,B> m1, matrix<T,A,B> m2)
{
    matrix<T,A,B> result;
    for (int i = 0; i < A; i++)
        result[i] = fmod(m1[i], m2[i]);
    return result;
}
)";

const char* MetalSourceEmitter::kMetalBuiltinPreludeSimdgroupMatrixOps = R"(
#include <metal_simdgroup_matrix>
template<typename T, int Cols, int Rows, typename V>
void _slang_simdgroup_fill(thread simdgroup_matrix<T, Cols, Rows>* dest, V val) {
    *dest = make_filled_simdgroup_matrix<T, Cols, Rows>(T(val));
}
template<typename Matrix, typename T>
Matrix _slang_simdgroup_load(const device T* src, ulong elements_per_row) {
    Matrix result;
    simdgroup_load(result, src, elements_per_row);
    return result;
}
template<typename Matrix, typename T>
Matrix _slang_simdgroup_load_transpose(const device T* src, ulong elements_per_row) {
    Matrix result;
    simdgroup_load(result, src, elements_per_row, ulong2(0), true);
    return result;
}
template<typename Matrix, typename T>
Matrix _slang_simdgroup_load(const threadgroup T* src, ulong elements_per_row) {
    Matrix result;
    simdgroup_load(result, src, elements_per_row);
    return result;
}
template<typename Matrix, typename T>
Matrix _slang_simdgroup_load_transpose(const threadgroup T* src, ulong elements_per_row) {
    Matrix result;
    simdgroup_load(result, src, elements_per_row, ulong2(0), true);
    return result;
}
)";

// Included on demand rather than in the front matter, since it only exists from MSL 3.2 onwards.
const char* MetalSourceEmitter::kMetalBuiltinPreludeLogging = R"(
#include <metal_logging>
)";

} // namespace Slang
